{
  "name": "封膜机后端控制组件",
  "name_en": "Sealer Backend Control Component",
  "manufacturer": "",
  "description": "这是一个非实体的软件控制组件，用于定义实验室封膜机的基础控制接口，包括封膜、温度设置与温度读取，供上层实验流程或具体硬件实现调用。",
  "description_en": "This is a non-physical software control component that defines the basic control interface for a laboratory sealer, including sealing, temperature setting, and temperature readback, for use by higher-level workflows or concrete hardware implementations.",
  "actions": [
    {
      "action_name": "auto-seal",
      "description": "按给定温度和持续时间执行一次封膜操作。",
      "description_en": "Execute one sealing operation using the specified temperature and duration."
    },
    {
      "action_name": "auto-set_temperature",
      "description": "设置封膜温度。",
      "description_en": "Set the sealing temperature."
    },
    {
      "action_name": "auto-get_temperature",
      "description": "读取当前封膜温度。",
      "description_en": "Get the current sealing temperature."
    }
  ],
  "tag_hints": [
    "sealer control interface",
    "thermal sealing",
    "temperature control",
    "lab automation",
    "non-physical software component"
  ]
}

